import{_ as l,C as c,o as t,c as h,a8 as i,b as s,w as a,a as o,E as r,a9 as d}from"./chunks/framework.DB1tY2mn.js";const w=JSON.parse('{"title":"Packet Diagram (v11.0.0+)","description":"","frontmatter":{"editLink":"https://github.com/mermaid-js/mermaid/edit/develop/packages/mermaid/src/docs/syntax/packet.md","head":[["link",{"rel":"canonical","href":"https://mermaid.ai/open-source/syntax/packet.html"}]]},"headers":[],"relativePath":"syntax/packet.md","filePath":"syntax/packet.md"}'),p={name:"syntax/packet.md"};function u(m,e,A,g,b,f){const n=c("Mermaid");return t(),h("div",null,[e[3]||(e[3]=i(`<h1 id="packet-diagram-v11-0-0" tabindex="-1">Packet Diagram (v11.0.0+) <a class="header-anchor" href="#packet-diagram-v11-0-0" aria-label="Permalink to &quot;Packet Diagram (v11.0.0+)&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>A packet diagram is a visual representation used to illustrate the structure and contents of a network packet. Network packets are the fundamental units of data transferred over a network.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><p>This diagram type is particularly useful for developers, network engineers, educators, and students who require a clear and concise way to represent the structure of network packets.</p><h2 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to &quot;Syntax&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>packet</span></span>
<span class="line"><span>start: &quot;Block name&quot; %% Single-bit block</span></span>
<span class="line"><span>start-end: &quot;Block name&quot; %% Multi-bit blocks</span></span>
<span class="line"><span>... More Fields ...</span></span></code></pre></div><h3 id="bits-syntax-v11-7-0" tabindex="-1">Bits Syntax (v11.7.0+) <a class="header-anchor" href="#bits-syntax-v11-7-0" aria-label="Permalink to &quot;Bits Syntax (v11.7.0+)&quot;">​</a></h3><p>Using start and end bit counts can be difficult, especially when modifying a design. For this we add a bit count field, which starts from the end of the previous field automagically. Use <code>+&lt;count&gt;</code> to set the number of bits, thus:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>packet</span></span>
<span class="line"><span>+1: &quot;Block name&quot; %% Single-bit block</span></span>
<span class="line"><span>+8: &quot;Block name&quot; %% 8-bit block</span></span>
<span class="line"><span>9-15: &quot;Manually set start and end, it&#39;s fine to mix and match&quot;</span></span>
<span class="line"><span>... More Fields ...</span></span></code></pre></div><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2>`,11)),(t(),s(d,null,{default:a(()=>[r(n,{id:"mermaid-29",showCode:!0,graph:"---%0Atitle%3A%20%22TCP%20Packet%22%0A---%0Apacket%0A0-15%3A%20%22Source%20Port%22%0A16-31%3A%20%22Destination%20Port%22%0A32-63%3A%20%22Sequence%20Number%22%0A64-95%3A%20%22Acknowledgment%20Number%22%0A96-99%3A%20%22Data%20Offset%22%0A100-105%3A%20%22Reserved%22%0A106%3A%20%22URG%22%0A107%3A%20%22ACK%22%0A108%3A%20%22PSH%22%0A109%3A%20%22RST%22%0A110%3A%20%22SYN%22%0A111%3A%20%22FIN%22%0A112-127%3A%20%22Window%22%0A128-143%3A%20%22Checksum%22%0A144-159%3A%20%22Urgent%20Pointer%22%0A160-191%3A%20%22(Options%20and%20Padding)%22%0A192-255%3A%20%22Data%20(variable%20length)%22%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),(t(),s(d,null,{default:a(()=>[r(n,{id:"mermaid-30",showCode:!0,graph:"packet%0Atitle%20UDP%20Packet%0A%2B16%3A%20%22Source%20Port%22%0A%2B16%3A%20%22Destination%20Port%22%0A32-47%3A%20%22Length%22%0A48-63%3A%20%22Checksum%22%0A64-95%3A%20%22Data%20(variable%20length)%22%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=i('<h2 id="details-of-syntax" tabindex="-1">Details of Syntax <a class="header-anchor" href="#details-of-syntax" aria-label="Permalink to &quot;Details of Syntax&quot;">​</a></h2><ul><li><strong>Ranges</strong>: Each line after the title represents a different field in the packet. The range (e.g., <code>0-15</code>) indicates the bit positions in the packet.</li><li><strong>Field Description</strong>: A brief description of what the field represents, enclosed in quotes.</li></ul><h3 id="bit-numbering-order-v-mermaid-release-version" tabindex="-1">Bit Numbering Order (v&lt;MERMAID_RELEASE_VERSION&gt;+) <a class="header-anchor" href="#bit-numbering-order-v-mermaid-release-version" aria-label="Permalink to &quot;Bit Numbering Order (v\\&lt;MERMAID_RELEASE_VERSION&gt;+)&quot;">​</a></h3><p>Rows are numbered from their lowest bit on the left up to their highest bit on the right, which suits network packets. Hardware registers are conventionally drawn the other way round, with the most significant bit on the left and bit 0 on the right. Set <code>bitOrder: descending</code> to mirror every row:</p>',4)),(t(),s(d,null,{default:a(()=>[r(n,{id:"mermaid-52",showCode:!0,graph:"---%0Aconfig%3A%0A%20%20packet%3A%0A%20%20%20%20showBits%3A%20true%0A%20%20%20%20bitOrder%3A%20descending%0A%20%20%20%20bitsPerRow%3A%2016%0A---%0Apacket%0A0-7%3A%20%22DATA%22%0A8-11%3A%20%22TYPE%22%0A12%3A%20%22EN%22%0A13-15%3A%20%22RESERVED%22%0A"})]),fallback:a(()=>[...e[2]||(e[2]=[o(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=i('<p>Only the drawing is mirrored. Fields are still declared lowest bit first (<code>0-7</code>, never <code>7-0</code>) and keep their width, so the same diagram can be switched between the two conventions by changing <code>bitOrder</code> alone.</p><p>Each row is mirrored on its own, so a packet wider than <code>bitsPerRow</code> reads as a stack of words that each run from their highest bit down to their lowest: with the default <code>bitsPerRow: 32</code>, the second row runs from bit 63 down to bit 32, not down to bit 0. A row that is not completely filled is padded on the left, keeping its lowest bit flush against the right edge.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Please refer to the <a href="/dochub/mermaid/config/schema-docs/config-defs-packet-diagram-config.html">configuration</a> guide for details.</p>',4))])}const _=l(p,[["render",u]]);export{w as __pageData,_ as default};
